from range(date '2020-01-01', date '2020-02-01', interval 1 day)

model.probe.customer_orders_inc.raw_code:
{{ config(materialized='incremental', unique_key='id') }}
select id, customer_id, amount_cents from {{ ref('orders') }}
{% if is_incremental() %} where id > (select max(id) from {{ this }}) {% endif %}

macro.probe.test_positive.macro_sql:
